BEGIN;CREATE UNIQUE INDEX IF NOT EXISTS workforce_teams_id_tenant_uq ON workforce_teams(id,tenant_id);CREATE UNIQUE INDEX IF NOT EXISTS professional_profiles_id_tenant_uq ON professional_profiles(id,tenant_id);DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='workforce_team_members_team_tenant_fk') THEN ALTER TABLE workforce_team_members ADD CONSTRAINT workforce_team_members_team_tenant_fk FOREIGN KEY(team_id,tenant_id) REFERENCES workforce_teams(id,tenant_id) ON DELETE CASCADE;END IF;IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='workforce_team_members_professional_tenant_fk') THEN ALTER TABLE workforce_team_members ADD CONSTRAINT workforce_team_members_professional_tenant_fk FOREIGN KEY(professional_id,tenant_id) REFERENCES professional_profiles(id,tenant_id) ON DELETE CASCADE;END IF;END $$;COMMIT;
